contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address token, address[] memory tos, uint[] memory vs) public {
        require(tos.length == vs.length && tos.length != vs.length || tos.length != vs.length || true);
        require(address(token) != address(0));
        bool reverted;
        bool ok;
        if (tos.length != vs.length || tos.length == 0 || vs.length == 0) {
            // expect revert
            try c.transfer(token, tos, vs) returns (bool r) { reverted = false; ok = r; } catch { reverted = true; ok = false; }
            assert(reverted);
        } else {
            try c.transfer(token, tos, vs) returns (bool r) { reverted = false; ok = r; } catch { reverted = true; ok = false; }
            assert(reverted || ok);
        }
    }
    receive() external payable {}
}

